// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        address owner = address(uint160(uint256(keccak256(abi.encodePacked("owner_marker")))));
        address trueOwner = address(this);

        uint256 before = c.balanceOf(trueOwner);

        vm.prank(caller);
        bool ok;
        try c.XBornID() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterOwner = c.balanceOf(trueOwner);

        if (caller != trueOwner) {
            assertTrue(afterOwner == before);
        } else {
            assertTrue(ok == true);
        }
    }
}
